"""Original inspection workflows. Case observations are fictional teaching examples."""
import re

NEW_GUIDES = []


def guide(title, product, category, description, scope, prerequisites, sources, rows, case):
    NEW_GUIDES.append(dict(
        id=re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-'), title=title,
        product=product, vendor=product, category=category, description=description,
        scope=scope, prerequisites=prerequisites, source=sources[0][1],
        sourceLabel=sources[0][0], sources=[dict(label=a, url=b) for a, b in sources],
        rows=[list(r[:2]) for r in rows], walkthrough=[r[2] for r in rows],
        kind='Command', level='Intermediate', time=12, updated='2026-11-02',
        case=dict(title=case[0], symptom=case[1],
                  steps=[dict(action=rows[i][0], purpose=rows[i][1], detail=detail)
                         for i, detail in case[2]],
                  evidence=case[3], interpretation=case[4], verification=case[5],
                  escalation=case[6])))


guide('Windows DNS resolution investigation', 'Windows', 'IT fundamentals',
      'Separate resolver selection, stale cache, missing records and service reachability in a Windows DNS incident.',
      'Windows 10/11 or Windows Server; PowerShell DnsClient and NetTCPIP modules.',
      'Replace app.corp.example, 10.20.0.10 and 10.20.1.25 with your internal service, resolver and expected address. Run from the affected client; queries and connection tests send traffic.',
      [('Microsoft Resolve-DnsName reference', 'https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname'),
       ('Microsoft DNS client module', 'https://learn.microsoft.com/en-us/powershell/module/dnsclient/'),
       ('Microsoft Test-NetConnection reference', 'https://learn.microsoft.com/en-us/powershell/module/nettcpip/test-netconnection')], [
          ('Get-DnsClientServerAddress -AddressFamily IPv4', 'Identify configured IPv4 resolvers',
           'Match InterfaceAlias to the adapter carrying this connection. VPN and physical adapters can use different resolvers. These are configured addresses, not proof that a query reached a server; record the adapter and resolver before testing.'),
          ('Resolve-DnsName app.corp.example -Type A -DnsOnly', 'Query the client DNS path',
           'Inspect the returned IPv4 addresses, aliases and TTLs. NXDOMAIN means the queried name does not exist according to that response; a timeout means no usable response arrived. Do not interpret those outcomes as the same fault.'),
          ('Resolve-DnsName app.corp.example -Server 10.20.0.10 -Type A -DnsOnly', 'Ask a selected resolver directly',
           'Compare this answer with the default query. A difference can indicate resolver selection, split DNS, replication lag or cache state. Query the other intended internal resolver as well before deciding that a record is incorrect.'),
          ('Get-DnsClientCache | Where-Object Entry -eq "app.corp.example"', 'Inspect matching local cache entries',
           'Compare cached data and remaining TTL with the intended record. An absent entry does not prove that the application has no cache of its own. Capture the evidence before considering an approved cache clear; this command changes nothing.'),
          ('Resolve-DnsName app.corp.example -Server 10.20.0.10 -Type AAAA -DnsOnly', 'Check the IPv6 answer separately',
           'An application can prefer IPv6 even when IPv4 is healthy. Compare any AAAA answer with the supported application path. No AAAA record is normal for an IPv4-only service; investigate an unexpected record rather than disabling IPv6.'),
          ('Test-NetConnection 10.20.1.25 -Port 443 -InformationLevel Detailed', 'Test TCP against the expected address',
           'Inspect TcpTestSucceeded, SourceAddress and InterfaceAlias. A successful IP-based TCP connection separates basic reachability from name resolution, but does not validate the certificate, HTTP host routing or application login.')],
      ('The intranet works by IP but not by name',
       'After a VPN change, a user cannot open app.corp.example. The expected internal IPv4 address is 10.20.1.25.',
       [(0, 'Record the VPN and LAN resolver lists. Establish which connection is active and retain both lists for the network team.'),
        (1, 'Capture the default answer and error type. In this example the default lookup returns NXDOMAIN.'),
        (2, 'Query the intended internal resolver. It returns 10.20.1.25, so the name exists on that DNS path.'),
        (3, 'Check for a cached result before changing anything. An old negative answer may persist for its negative-cache lifetime.'),
        (5, 'Test the expected IP and service port. A successful connection narrows the incident toward DNS selection or caching.')],
       'Illustrative findings: default lookup = NXDOMAIN; selected internal resolver = 10.20.1.25; TcpTestSucceeded = True.',
       'The internal record and TCP service are available in this example. The failing client DNS path deserves investigation; these findings do not prove whether the VPN policy, resolver order or a cache is responsible.',
       'After the DNS or VPN owner applies the approved correction, repeat the default A and AAAA queries, then open the application by name and verify its certificate and login from the affected client.',
       'Escalate with the query time, adapter, VPN state, both resolver answers and expected record. Ask the DNS owner to compare authoritative data and split-DNS policy.'))

guide('Windows DHCP scope and lease investigation', 'Windows', 'Infrastructure',
      'Inspect DHCP scope capacity, leases, reservations, options and failover before changing a production scope.',
      'Windows Server DHCP with the DhcpServer PowerShell module or RSAT DHCP tools.',
      'Use authorized read access. Replace dhcp01.corp.example and 10.20.30.0 with the DHCP server and scope network ID, not a client address. These commands query the server without releasing leases.',
      [('Microsoft DHCP Server cmdlets', 'https://learn.microsoft.com/en-us/powershell/module/dhcpserver/')], [
          ('Get-DhcpServerv4Scope -ComputerName dhcp01.corp.example', 'List scopes and their configured state',
           'Find the affected subnet by ScopeId and inspect State, StartRange, EndRange and SubnetMask. An active scope is necessary but does not confirm that the client VLAN can reach the server or that the relay targets this server.'),
          ('Get-DhcpServerv4ScopeStatistics -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0', 'Measure scope utilization',
           'Compare AddressesFree, AddressesInUse and PercentageInUse with the incident time. A nearly exhausted pool can explain new-client failures while existing clients keep working; retain the sample time and compare with another sample.'),
          ('Get-DhcpServerv4Lease -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0', 'Inspect allocated leases',
           'Find the affected client using its address, client identifier and host name. Compare AddressState and LeaseExpiryTime. A client absent from this server may have contacted another server or never reached DHCP; absence alone cannot distinguish those cases.'),
          ('Get-DhcpServerv4Reservation -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0', 'Review scope reservations',
           'Compare reserved addresses and client identifiers with the intended equipment. A reservation is not evidence that a client is online, and a MAC or client-ID mismatch can prevent the expected assignment. Do not remove reservations during evidence collection.'),
          ('Get-DhcpServerv4OptionValue -ComputerName dhcp01.corp.example -ScopeId 10.20.30.0', 'Inspect configured scope options',
           'Compare router option 003 and DNS server option 006 with the subnet design. Scope options do not tell the entire story when server defaults, policies or reservation-level overrides apply; compare the actual client configuration too.'),
          ('Get-DhcpServerv4Failover -ComputerName dhcp01.corp.example', 'Inspect configured failover relationships',
           'Record partner, relationship state and associated scopes. No relationship can be intentional on a standalone server. An unexpected communication state requires checking partner health and connectivity before any manual state transition.')],
      ('Existing laptops work but new clients receive no lease',
       'New devices on VLAN 30 cannot obtain an address, while machines with current leases remain connected.',
       [(0, 'Confirm VLAN 30 maps to the active 10.20.30.0 scope. A wrong or inactive scope leads to a different investigation.'),
        (1, 'Read available addresses at the time a new client tries to connect. This example has zero free addresses.'),
        (2, 'Inspect lease distribution and expiration times. Do not delete apparently unused leases based only on host names.'),
        (3, 'Compare reservations with the approved allocation plan, looking for unexpected consumption or client-ID mismatches.'),
        (5, 'Check the failover partner state before attributing all available capacity to one server.')],
       'Illustrative findings: State = Active; AddressesFree = 0; existing leases remain valid; failover relationship state = Normal.',
       'Exhaustion is supported by the capacity sample. It does not establish why addresses were consumed. Review lease growth and address planning with the DHCP owner before changing ranges or lease duration.',
       'After the approved capacity correction, have one test client request a lease normally. Confirm its subnet, gateway, DNS options and lease on the server, then repeat the free-address sample.',
       'Send the scope ID, utilization samples, lease counts and partner state to the DHCP owner. If free addresses exist, investigate VLAN relay, server reachability and DHCP logs instead.'))

guide('Linux systemd service failure triage', 'Linux', 'IT fundamentals',
      'Connect service state, exit codes, unit configuration and journal events without hiding evidence behind a restart.',
      'Linux distributions running systemd; examples use nginx.service, whose unit name varies by distribution.',
      'Replace nginx.service with the affected unit. Use an account permitted to read its journal and configuration. status exits nonzero for a failed unit; that is useful evidence, not a reason to restart it.',
      [('systemctl manual', 'https://www.freedesktop.org/software/systemd/man/latest/systemctl.html'),
       ('journalctl manual', 'https://www.freedesktop.org/software/systemd/man/latest/journalctl.html')], [
          ('systemctl status nginx.service --no-pager --full', 'Capture service state and recent messages',
           'Record Loaded, Active, Main PID and the failure timestamp. The short log excerpt can omit the original cause, so use it as a starting point. A failed unit can still have unrelated processes listening on the same application port.'),
          ('systemctl show nginx.service -p ActiveState -p SubState -p Result -p ExecMainStatus -p NRestarts', 'Read machine-friendly failure fields',
           'Compare Result and ExecMainStatus with the service documentation. A nonzero application exit code is different from a timeout or signal. NRestarts records automatic restarts tracked by the manager, not every historical manual start.'),
          ('journalctl -u nginx.service --since "30 minutes ago" -n 100 --no-pager -o short-iso', 'Read a bounded incident window',
           'Look for the first error before repeated restart messages. Correlate ISO timestamps with the reported interruption. Empty results can reflect permissions, retention or a wrong unit name; they do not prove that the service produced no errors.'),
          ('systemctl cat nginx.service', 'Inspect the unit and drop-in files',
           'Read ExecStart, User, dependencies and any override files. This shows files on disk; if they changed without a daemon reload, the manager may still use older settings. Compare the configured executable and account with the journal error.'),
          ('systemctl list-dependencies nginx.service --no-pager', 'Inspect declared dependencies',
           'Check required units and their state, then investigate any dependency named in the failure log. This is the unit dependency graph, not a full map of DNS, databases or other external services the application needs.'),
          ('ss -ltnp', 'Compare expected TCP listeners with processes',
           'Find the expected port and local binding. Loopback-only and all-interface listeners serve different paths. Process information can require elevated privileges; an occupied port may explain a bind failure but does not identify the correct owner by itself.')],
      ('A web service fails immediately after a deployment',
       'The nginx unit fails at startup after an application deployment. Capture evidence before requesting a restart.',
       [(0, 'Record the failed state and the first reported failure time.'),
        (2, 'Read the incident window. In this fictional example the journal reports that binding to port 80 failed because the address is already in use.'),
        (3, 'Check the intended executable and drop-ins so that the unit being examined is actually the expected web server.'),
        (5, 'Identify the listener on port 80. The example has a separate process holding the port; record its PID for the service owner.')],
       'Illustrative findings: Active = failed; journal contains an address-in-use bind error; ss shows another process listening on TCP 80.',
       'A port conflict is supported. Do not kill the listener until its owner and purpose are established. The deployment may have introduced a second service or changed a binding.',
       'After the owner resolves the conflicting configuration and performs an approved start, repeat status, journal and listener checks, then test the application through its normal URL.',
       'Provide unit/drop-in paths, the first failure message, timestamps and listener PID to the application owner. Remove credentials from configuration excerpts.'))

guide('Linux disk space and inode investigation', 'Linux', 'Infrastructure',
      'Distinguish exhausted bytes, exhausted inodes, mount layout and directory growth before deleting any files.',
      'Linux with GNU coreutils and util-linux. Commands inspect mounted filesystems and may take time on large directory trees.',
      'Replace /var with the affected path. Directory traversal may need additional read permissions. Stay on the selected filesystem when measuring; this workflow performs no cleanup or filesystem repair.',
      [('Linux lsblk manual', 'https://man7.org/linux/man-pages/man8/lsblk.8.html'),
       ('GNU disk usage documentation', 'https://www.gnu.org/software/coreutils/manual/html_node/Disk-usage.html'),
       ('Linux findmnt manual', 'https://man7.org/linux/man-pages/man8/findmnt.8.html')], [
          ('df -hT /var', 'Inspect filesystem byte capacity',
           'Read the filesystem, mountpoint, type, Available and Use% for this path. A full parent or separate mount can affect only part of the server. Human-readable rounded values are useful for triage; compare the same mount across samples.'),
          ('df -i /var', 'Inspect inode capacity',
           'Check IFree and IUse% on filesystems with fixed inode accounting. A workload creating many tiny files can exhaust inodes while gigabytes remain free. Some filesystem types allocate metadata differently, so interpret these fields with their documentation.'),
          ('findmnt -T /var', 'Identify the mount serving a path',
           'Record SOURCE, TARGET, FSTYPE and mount options. A read-only mount can explain write failures even when capacity remains. Compare the selected mount with the expected volume before attributing usage to a directory on another filesystem.'),
          ('lsblk -o NAME,SIZE,FSTYPE,MOUNTPOINTS', 'Map block devices to filesystems',
           'Trace the mounted filesystem back to its disk, partition or logical device. A large disk does not mean the filesystem has been expanded to use it. MOUNTPOINTS availability depends on util-linux version; use MOUNTPOINT on older releases.'),
          ('du -xhd1 /var', 'Measure first-level directory byte usage',
           'Compare the largest immediate directories while staying on one filesystem. du reports accessible linked files, whereas df reports filesystem allocation, so deleted-open files, metadata, reserved space and permission failures can explain a difference.'),
          ('du --inodes -x --max-depth=1 /var', 'Locate directories consuming many inodes',
           'On GNU du, compare inode counts by immediate directory when df -i indicates pressure. A large count points toward many files rather than a single large log. Inspect the responsible application and its retention policy before authorizing cleanup.')],
      ('An application says no space left despite free gigabytes',
       'A queue worker cannot create new files under /var. The monitoring dashboard still shows several gigabytes free.',
       [(0, 'Confirm the failing path is on the filesystem represented in the dashboard.'),
        (1, 'Read inode utilization. This example reports IFree = 0 despite available bytes.'),
        (2, 'Verify the actual mount and options so a separate queue volume is not confused with the root filesystem.'),
        (5, 'Compare directory inode counts. The example concentrates millions of small entries under the application queue.')],
       'Illustrative findings: Available = 8G; IUse% = 100%; the application queue dominates the inode count.',
       'The immediate limit is inode availability, not byte capacity. Application retention or a stuck queue may explain growth; deleting arbitrary queue entries could lose work.',
       'After the application owner performs approved retention or queue recovery, repeat df -i and the directory count. Confirm that a normal application operation creates and processes a new item.',
       'Share the mount, inode samples, growth window and directory counts with the application/storage owners. If df and du disagree, ask for an investigation of deleted-open files and filesystem accounting.'))

guide('Docker container health and restart investigation', 'Docker', 'Infrastructure',
      'Inspect container exit state, health checks, bounded logs, resource usage and published ports during a restart incident.',
      'Docker Engine CLI; examples use a container named web. Health fields exist only when a health check is configured.',
      'Confirm your Docker context and replace web with the affected container. Use authorized daemon access. No command here restarts, removes or executes code inside a container.',
      [('Docker container CLI reference', 'https://docs.docker.com/reference/cli/docker/container/'),
       ('Docker container inspect', 'https://docs.docker.com/reference/cli/docker/container/inspect/'),
       ('Docker container logs', 'https://docs.docker.com/reference/cli/docker/container/logs/'),
       ('Docker container stats', 'https://docs.docker.com/reference/cli/docker/container/stats/')], [
          ('docker context show', 'Confirm the selected Docker context',
           'Record the context before collecting evidence. The same container name may exist on a local workstation and a remote daemon. Also check whether DOCKER_HOST or command-line endpoint flags override where your investigation is directed.'),
          ('docker ps -a --filter name=web', 'Find the container and its status',
           'Inspect the container ID, image, status and published ports. The name filter can match multiple names; select the exact ID for follow-up queries. A running state does not prove application readiness or a passing health check.'),
          ('docker inspect --format "{{json .State}}" web', 'Inspect exit and health state',
           'Read Status, ExitCode, OOMKilled, Error and timestamps. When present, Health includes probe results. OOMKilled supports a memory-kill investigation; exit code 137 alone does not prove an OOM kill because other SIGKILL paths can produce it.'),
          ('docker logs --since 30m --tail 100 --timestamps web', 'Read bounded application logs',
           'Correlate the first application error with the start and finish timestamps. Logs generally reflect stdout and stderr, and availability depends on the logging driver. Redact tokens and connection strings before attaching excerpts to an incident.'),
          ('docker stats --no-stream web', 'Take one resource-usage sample',
           'Record memory use, limit, CPU and block I/O for a running container. A single sample cannot establish the peak immediately before a crash. Compare multiple timed samples with host monitoring and the recorded exit state.'),
          ('docker port web', 'Inspect published host port mappings',
           'Compare the container port and host binding with the URL users reach. A published mapping does not prove that the process is listening inside the container or that the host firewall and upstream load balancer permit traffic.')],
      ('A web container repeatedly exits during peak traffic',
       'Users see intermittent failures and the web container repeatedly starts and exits under load.',
       [(0, 'Confirm that the CLI targets the production daemon named in the incident.'),
        (1, 'Capture the exact container ID and image so a replacement is not confused with the original container.'),
        (2, 'Read the stored exit state. This example has OOMKilled = true and ExitCode = 137.'),
        (3, 'Compare the last logs with the exit timestamp; missing shutdown logs are consistent with a forced kill but do not explain memory growth.'),
        (4, 'If the container is running, sample its memory and correlate with host metrics. If stopped, record that stats cannot show its previous peak.')],
       'Illustrative findings: OOMKilled = true; ExitCode = 137; monitoring records memory approaching the configured limit before each exit.',
       'The evidence supports a memory kill. It does not distinguish a leak, insufficient sizing or a traffic spike. Increasing limits without checking host capacity can move the failure to the host.',
       'After an approved application or resource change, observe the same traffic window. Confirm stable uptime, passing health checks if configured, memory headroom and successful requests through the published service.',
       'Send container/image IDs, exit timestamps, configured limits and monitoring graphs to the application/platform owners. Do not include a full inspect dump containing environment secrets.'))

guide('Kubernetes pod crash and readiness investigation', 'Kubernetes', 'Cloud',
      'Trace a failing pod through context, scheduling, container state, current logs, previous logs and namespace events.',
      'kubectl against a supported Kubernetes cluster. Examples target namespace production, pod web-abc123 and container web.',
      'Replace namespace, pod and container names. Confirm cluster context and RBAC read access. Pod replacement changes the name and UID; use the pod that exists in the incident window.',
      [('Kubernetes pod debugging', 'https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/'),
       ('kubectl reference', 'https://kubernetes.io/docs/reference/kubectl/'),
       ('kubectl logs reference', 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/')], [
          ('kubectl config current-context', 'Confirm the selected cluster context',
           'Record the context and compare it with the incident environment. A context name is locally configured and can be misleading; verify the intended cluster through your approved inventory before interpreting workload results.'),
          ('kubectl get pods -n production -o wide', 'Inspect pod readiness, restarts and placement',
           'Find the affected pod and note Ready, Status, Restarts, age and node. Running is a lifecycle phase, not a guarantee that every container is ready. Pending requires scheduling investigation; a crash loop requires container-state and log inspection.'),
          ('kubectl describe pod web-abc123 -n production', 'Inspect container states, probes and events',
           'Read current State, Last State, exit reason, readiness/liveness probes and events. OOMKilled, failed probes and image-pull failures lead to different investigations. A failing readiness probe removes readiness; a failing liveness probe can trigger a restart.'),
          ('kubectl logs web-abc123 -n production -c web --since=30m --tail=100 --timestamps=true', 'Read the current container logs',
           'Use the explicit container name in multi-container pods. Correlate timestamps with restarts and probes. Empty current logs may simply mean that the newest container has barely started; examine the previous container instance if it exists.'),
          ('kubectl logs web-abc123 -n production -c web --previous --tail=100 --timestamps=true', 'Read the previous terminated instance',
           'Look for the first fatal message before termination. Previous logs cover the prior container instance in this pod, not every historical restart or a deleted pod. Unavailable logs require your centralized logging system or node-level investigation.'),
          ('kubectl get events -n production --sort-by=.metadata.creationTimestamp', 'Correlate recent namespace events',
           'Match involved object names, messages and times to the pod under investigation. Events are retained for a limited period and can aggregate repeated occurrences. A broad namespace list may include unrelated failures, so do not infer causality from proximity alone.')],
      ('A deployment has Running pods but no ready replicas',
       'After a rollout, a web pod appears Running but shows 0/1 Ready and an increasing restart count.',
       [(0, 'Confirm the cluster context before querying the production namespace.'),
        (1, 'Record the pod name, node and restart count twice to determine whether restarts are still increasing.'),
        (2, 'Read the termination reason and probe events. This example shows a nonzero application exit rather than OOMKilled.'),
        (4, 'Read previous logs. The fictional log reports a missing required configuration key at startup.'),
        (5, 'Correlate rollout timing and restart events without dumping Secret values into the incident ticket.')],
       'Illustrative findings: Ready = 0/1; restart count increases; previous logs report a required configuration key missing; no OOMKilled reason.',
       'The startup configuration is the leading hypothesis. A readiness failure alone would not explain repeated restarts; correlate application exits and liveness events before deciding on the trigger.',
       'After the owner corrects the deployment configuration through the approved rollout, inspect the replacement pods. Confirm all expected containers are ready, restart counts stay stable, and the service responds through its normal route.',
       'Provide namespace, pod UID/name, image, first fatal message and relevant event times to the workload owner. Record configuration key names without exposing Secret values.'))

guide('HTTP and TLS troubleshooting with curl', 'curl', 'Networking',
      'Separate DNS, TCP, certificate validation, redirects and HTTP status with bounded curl requests.',
      'curl on Linux/macOS or curl.exe on Windows. Commands below use POSIX shell quoting; use curl.exe in Windows PowerShell.',
      'Replace app.example.com and 192.0.2.25 with an approved endpoint and expected IP. Requests contact the service. Commands retain certificate verification and send no authentication token.',
      [('curl official command manual', 'https://curl.se/docs/manpage.html')], [
          ('curl --version', 'Identify curl features and TLS backend',
           'Record the version, TLS backend and supported protocols. Different builds can use different certificate stores and proxy behavior. On Windows invoke curl.exe explicitly if PowerShell resolves curl to Invoke-WebRequest.'),
          ('curl --head --connect-timeout 5 --max-time 15 https://app.example.com/', 'Inspect the first HTTP response headers',
           'Read the status and Location header without following redirects. HEAD can behave differently from GET and may be unsupported, so a 405 response is not proof that normal browsing fails. Connection and total timeouts bound the attempt.'),
          ('curl --silent --show-error --output /dev/null --write-out "code=%{http_code} dns=%{time_namelookup} tcp=%{time_connect} tls=%{time_appconnect} total=%{time_total}\\n" --connect-timeout 5 --max-time 15 https://app.example.com/', 'Compare request timing checkpoints',
           'The timing values are cumulative checkpoints from request start, not independent phase durations. Subtract adjacent checkpoints cautiously; proxies, reuse and redirects change interpretation. On Windows replace /dev/null with NUL. HTTP 4xx/5xx can still have a zero curl exit code.'),
          ('curl --verbose --output /dev/null --connect-timeout 5 --max-time 15 https://app.example.com/', 'Inspect connection and certificate diagnostics',
           'Inspect the resolved address, proxy use, TLS negotiation and certificate error if any. Verbose output can contain headers and sensitive connection details, so redact before sharing. Keep verification enabled; use NUL instead of /dev/null on Windows.'),
          ('curl --head --location --max-redirs 5 --connect-timeout 5 --max-time 20 https://app.example.com/', 'Trace a bounded redirect chain',
           'Compare each status and Location with the expected canonical host and login flow. A loop or unexpected destination can explain browser failures. HEAD redirects are still not a full test of a GET request or an authenticated user session.'),
          ('curl --head --resolve app.example.com:443:192.0.2.25 --connect-timeout 5 --max-time 15 https://app.example.com/', 'Test one endpoint while preserving hostname checks',
           'This pins the host/port to the selected address while retaining the URL hostname for TLS and HTTP routing. It isolates DNS selection without disabling certificate verification. An active proxy can change the connection path; inspect proxy use first.')],
      ('A site fails after a DNS migration',
       'A browser reports a certificate error after an application moves to a new load balancer.',
       [(0, 'Record the TLS backend so differences in trust stores between the browser and CLI can be investigated.'),
        (3, 'Capture the selected destination and certificate failure. In this example the default DNS path reaches an old endpoint with the wrong hostname certificate.'),
        (5, 'Pin the expected new endpoint while preserving app.example.com. The example succeeds with normal verification.'),
        (4, 'Trace the redirect chain on the intended path and confirm that a later redirect is not sending users back to the old hostname.')],
       'Illustrative findings: default request fails hostname verification; the --resolve request to the approved new address returns HTTP 200 with certificate verification enabled.',
       'The result supports an endpoint-selection or DNS-transition problem. It does not prove the authoritative record is wrong; a recursive cache, hosts override, split DNS or proxy can select the old endpoint.',
       'After the approved DNS/load-balancer correction and applicable cache expiry, repeat the default request without --resolve. Verify the certificate, final URL and normal browser session from affected networks.',
       'Send the hostname, resolved addresses, error text, TLS backend and pin-test result to the DNS/load-balancer owner. Do not solve a hostname error by disabling certificate checks.'))

guide('AWS EC2 network path inspection', 'AWS', 'Cloud',
      'Connect AWS identity, instance state, subnets, route tables, security groups and network ACLs in one inspection workflow.',
      'AWS CLI v2 with an existing authenticated profile and read permissions for STS and EC2. Examples use eu-west-1.',
      'Replace the profile, region, instance, subnet, VPC and security-group IDs. Confirm the incident account first. AWS APIs return configuration; these commands do not run packet probes or change rules.',
      [('AWS EC2 describe-instances', 'https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-instances.html'),
       ('AWS EC2 describe-route-tables', 'https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-route-tables.html'),
       ('AWS EC2 describe-security-groups', 'https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-security-groups.html'),
       ('AWS EC2 describe-network-acls', 'https://docs.aws.amazon.com/cli/latest/reference/ec2/describe-network-acls.html'),
       ('AWS STS get-caller-identity', 'https://docs.aws.amazon.com/cli/latest/reference/sts/get-caller-identity.html')], [
          ('aws sts get-caller-identity --profile production --region eu-west-1', 'Confirm the account and principal',
           'Compare Account and Arn with the approved environment. A profile label does not prove account identity. Authentication failure must be resolved through the normal sign-in flow before interpreting missing resources as an infrastructure problem.'),
          ('aws ec2 describe-instances --instance-ids i-0123456789abcdef0 --profile production --region eu-west-1', 'Inspect the target instance and interfaces',
           'Record State, VpcId, SubnetId, private addresses and security groups on the actual network interface. A running instance can still have a failing guest OS or application. Wrong-region queries can look like missing resources.'),
          ('aws ec2 describe-instance-status --instance-ids i-0123456789abcdef0 --include-all-instances --profile production --region eu-west-1', 'Check instance and system status checks',
           'Distinguish system status, instance status and any scheduled events. Passed checks do not establish application readiness, DNS correctness or allowed service ports; use them to separate infrastructure signals from later path checks.'),
          ('aws ec2 describe-route-tables --filters Name=vpc-id,Values=vpc-0123456789abcdef0 --profile production --region eu-west-1', 'Identify the subnet route table and main fallback',
           'Find an explicit association for the instance subnet; otherwise use the VPC main route table. Inspect destination-specific routes, target and State, including blackhole entries. Listing only explicit subnet associations can miss the main-table fallback.'),
          ('aws ec2 describe-security-groups --group-ids sg-0123456789abcdef0 --profile production --region eu-west-1', 'Inspect a security group attached to the interface',
           'Compare protocol, ports and source or destination with the actual flow. Evaluate all groups attached to the interface because allowed rules combine. Security groups are stateful, but that does not override network ACLs, guest firewalls or missing routes.'),
          ('aws ec2 describe-network-acls --filters Name=association.subnet-id,Values=subnet-0123456789abcdef0 --profile production --region eu-west-1', 'Inspect the subnet network ACL',
           'Evaluate the first matching rule in ascending rule-number order in each direction. ACLs are stateless, so include the response path and appropriate ephemeral ports. Confirm the effective client address when traffic passes through NAT or a load balancer.')],
      ('An instance runs but HTTPS clients time out',
       'An EC2 application is running, yet an approved client network cannot connect to TCP 443 after a subnet change.',
       [(0, 'Record the account and principal to avoid examining a similarly named workload in another environment.'),
        (1, 'Identify the actual subnet and every security group attached to the serving interface.'),
        (3, 'Resolve the effective subnet route table, including the main fallback, and trace the return destination.'),
        (4, 'Check inbound 443 against the real client source. In this example the security group permits it.'),
        (5, 'Read ACL rules in order in both directions. The fictional example has an outbound rule denying the client ephemeral-port range before an allow rule.')],
       'Illustrative findings: instance = running; security group permits inbound TCP 443; effective ACL has an earlier outbound deny matching response traffic.',
       'The ACL is a supported path blocker in this example. It is not evidence that the application is healthy. Validate the client address and response ports against real flow evidence before changing a rule.',
       'After the network owner applies a least-privilege correction, repeat configuration checks and perform an approved HTTPS request from the original client. Confirm application response and return traffic.',
       'Provide account, region, ENI/subnet, effective route table, all attached groups, ordered ACL rules and client flow tuple. Escalate guest listener and host-firewall checks to the instance owner.'))


guide('Git working tree and merge conflict inspection', 'Git', 'IT fundamentals',
      'Separate staged, unstaged, untracked and conflicted files before choosing a commit or recovery action.',
      'Git CLI in an existing trusted repository. These commands inspect local state without fetching, resetting or resolving conflicts.',
      'Run from the affected checkout. Replace src/app.js with a real conflicted path. Remote-tracking information can be stale until a separately approved fetch; preserve local changes before planning recovery.',
      [('Git status reference', 'https://git-scm.com/docs/git-status'),
       ('Git diff reference', 'https://git-scm.com/docs/git-diff'),
       ('Git ls-files reference', 'https://git-scm.com/docs/git-ls-files')], [
          ('git status --short --branch', 'Summarize the branch and file states',
           'Read the two status columns separately: the first describes the index and the second the working tree, with special combinations for conflicts. Untracked files appear separately. Upstream ahead/behind counts depend on the last locally known remote state.'),
          ('git diff --stat', 'Measure unstaged tracked changes',
           'This summarizes differences between tracked working files and the index. It excludes staged-only changes and untracked files, so a blank result does not mean the checkout is clean. Compare it with status before concluding that work is missing.'),
          ('git diff --cached --stat', 'Measure changes staged for the next commit',
           'Inspect what the index contains relative to HEAD. A file can have both staged and unstaged edits; compare both diff summaries. The staged snapshot is what a normal commit records, not necessarily the entire current file on disk.'),
          ('git diff --name-only --diff-filter=U', 'List unresolved conflict paths',
           'Collect paths with unmerged index entries before editing. The list does not determine which side is correct or whether a merge versus rebase is in progress; read the full status message for the operation and its next steps.'),
          ('git ls-files -u -- src/app.js', 'Inspect unmerged index stages for one file',
           'Read the stage numbers and object IDs. For a typical content conflict, stages 1, 2 and 3 represent base and the two sides; add/delete conflicts can omit stages. During a rebase, intuitive meanings of ours and theirs can differ from a normal merge.'),
          ('git log -5 --oneline --decorate', 'Locate the current commit in recent history',
           'Compare HEAD and visible branch labels with the expected checkout. This shows local history, not evidence that a push succeeded. Detached HEAD can be intentional in CI or inspection work; do not move branch pointers just to change its appearance.')],
      ('A file seems missing from the next commit',
       'A developer edits several files during a merge, but the staged diff contains only part of the work.',
       [(0, 'Read the status columns and identify files with both staged and unstaged changes.'),
        (1, 'Compare the unstaged summary with the intended change; an edited file can be absent from the staged snapshot.'),
        (2, 'Inspect the actual staged file set rather than assuming every visible editor change will be committed.'),
        (3, 'Check for unresolved paths before recommending a commit or proceeding with the merge.')],
       'Illustrative findings: status reports MM for one file and UU for another; the staged summary omits the newest working-tree edit.',
       'The index and working tree contain different snapshots, and a separate conflict remains unresolved. These are two issues; staging everything blindly would not establish that the conflict resolution is correct.',
       'After reviewing and resolving the intended edits, repeat status and both diffs. Verify the staged patch contains only the approved change and that no unmerged paths remain before committing.',
       'Provide the branch, operation in progress, affected paths and relevant patch excerpts to the repository owner. Preserve the checkout; avoid reset or clean as a diagnostic shortcut.'))

guide('Ansible inventory and playbook preflight', 'Ansible', 'Infrastructure',
      'Check configuration, inventory groups, resolved host variables and selected playbook hosts before running automation.',
      'ansible-core CLI on the control node. Use a trusted inventory and playbook; plugins, inventory scripts and lookups can execute code even during preflight.',
      'Replace inventory.ini, site.yml and web01 with local trusted inputs. These examples do not execute playbook tasks. Inventory output can include secrets; keep variable dumps private.',
      [('Ansible inventory CLI', 'https://docs.ansible.com/projects/ansible/latest/cli/ansible-inventory.html'),
       ('Ansible playbook CLI', 'https://docs.ansible.com/projects/ansible/latest/cli/ansible-playbook.html'),
       ('Ansible configuration CLI', 'https://docs.ansible.com/projects/ansible/latest/cli/ansible-config.html')], [
          ('ansible --version', 'Identify runtime and configuration file',
           'Record ansible-core version, Python interpreter and the selected configuration file. A shell in another directory or virtual environment can load different settings; compare the actual paths with the automation runner before investigating hosts.'),
          ('ansible-config dump --only-changed', 'Inspect effective nondefault configuration',
           'Review changed settings and their origin, especially inventory and collection paths. This is not the resolved set of every host variable. Redact credentials or sensitive paths before sharing the output outside the control-node team.'),
          ('ansible-inventory -i inventory.ini --graph', 'Inspect inventory group membership',
           'Confirm that the intended host belongs to the group referenced by the playbook. A parse warning or an empty group points toward inventory selection or syntax. A valid graph does not prove that SSH access or task privileges will work.'),
          ('ansible-inventory -i inventory.ini --host web01', 'Inspect resolved inventory variables for one host',
           'Compare ansible_host, connection type and group-derived variables with the intended target. The alias may differ from its DNS name. Treat the output as sensitive because inventory variables can contain passwords and tokens.'),
          ('ansible-playbook -i inventory.ini site.yml --list-hosts', 'List hosts selected by the playbook',
           'Compare each play host pattern with the expected maintenance scope. This does not execute tasks or test connectivity. Additional limit flags in the real runner can narrow the selected set further, so compare the exact production command.'),
          ('ansible-playbook -i inventory.ini site.yml --syntax-check', 'Check playbook syntax without running tasks',
           'Resolve reported YAML, task or collection-loading errors before execution. Passing syntax checks does not validate runtime variables, network access, task behavior or dynamically included content in every possible branch.')],
      ('A playbook reports no hosts matched',
       'An operator expects a web-server maintenance play to select web01, but the automation runner selects zero hosts.',
       [(0, 'Record the config file and runtime used in the failing shell; compare them with the runner.'),
        (2, 'Inspect the inventory graph. In this example web01 belongs to webservers, while no web group exists.'),
        (4, 'List playbook hosts with the same inventory. The fictional play targets web, producing an empty selection.'),
        (5, 'Check syntax separately so a syntactically valid playbook is not confused with correct targeting.')],
       'Illustrative findings: inventory has webservers/web01; the play targets web; syntax check passes; list-hosts returns zero targets.',
       'The host-pattern mismatch explains the empty selection in this example. Syntax success does not prove that a play targets the intended equipment.',
       'After the owner corrects the approved inventory or play pattern, repeat the graph and list-hosts checks with the runner exact arguments. Review the selected hosts before scheduling execution.',
       'Send the configuration path, inventory path, group names and selected host count to the automation owner. Share variable names rather than secret values.'))

guide('Terraform workspace and state inspection', 'Terraform', 'Cloud',
      'Verify the active workspace, provider requirements, configuration validity and recorded resources before planning infrastructure changes.',
      'Terraform CLI in an already initialized, trusted configuration directory with the intended backend access.',
      'Use the approved checkout and installed providers. Replace aws_instance.web with a real state address. These commands do not apply changes; state output can expose infrastructure identifiers and sensitive values.',
      [('Terraform state list', 'https://developer.hashicorp.com/terraform/cli/commands/state/list'),
       ('Terraform state show', 'https://developer.hashicorp.com/terraform/cli/commands/state/show'),
       ('Terraform validate', 'https://developer.hashicorp.com/terraform/cli/commands/validate'),
       ('Terraform workspace show', 'https://developer.hashicorp.com/terraform/cli/commands/workspace/show')], [
          ('terraform version', 'Record CLI and installed provider versions',
           'Compare the CLI and provider versions with the project constraints and lock file. A local version difference can explain validation behavior. Version output alone does not prove that the correct backend or cloud account is selected.'),
          ('terraform workspace show', 'Identify the selected CLI workspace',
           'Compare the workspace name with the deployment process. A workspace is a state selection mechanism, not proof of cloud account identity. HCP Terraform workspace mapping and backend configuration require their own verification.'),
          ('terraform providers', 'Inspect provider requirements by module',
           'Compare provider requirements from configuration and state with the expected modules. This helps identify an unexpected dependency or migration gap; it does not query whether the remote resource is healthy or whether credentials are valid.'),
          ('terraform validate', 'Validate configuration in the initialized directory',
           'Read errors about configuration structure, types and provider schema. Required modules and providers must already be installed. Validation does not compare real infrastructure with state or establish that a later plan will be accepted by an API.'),
          ('terraform state list', 'List addresses in the selected state',
           'Find the expected module and resource addresses. Empty state can mean a new workspace, wrong backend, wrong workspace or genuinely unmanaged infrastructure. Do not import or create resources until the state-selection question is settled.'),
          ("terraform state show 'aws_instance.web'", 'Inspect one recorded resource',
           'Use the exact address from state list, preserving quotes for indexed addresses where required. This displays recorded state and does not refresh remote facts. Protect the output; it can include sensitive values and internal resource details.')],
      ('A resource exists in the cloud but not in state list',
       'An engineer is preparing a change and cannot find the production instance in the current Terraform state.',
       [(1, 'Check the active workspace. This example reports default rather than the intended production workspace.'),
        (2, 'Compare the module/provider layout with the repository used by the production pipeline.'),
        (4, 'Record the current state addresses without importing or creating anything.'),
        (3, 'Validate configuration separately; a valid configuration does not make the state selection correct.')],
       'Illustrative findings: current workspace = default; state list is empty; the production runner is documented to use another state selection.',
       'A state-selection mismatch is the leading explanation. The cloud resource existing does not mean that importing it into this empty state is appropriate; it may already belong to the intended production state.',
       'After the owner selects the approved backend/workspace through the normal process, repeat workspace show and state list. Compare recorded resource identity with the cloud account before requesting a reviewed plan.',
       'Provide the checkout revision, workspace, backend identity and expected resource address to the infrastructure owner. Avoid publishing state contents or changing backend settings during evidence collection.'))

guide('Redis memory and latency investigation', 'Redis', 'Infrastructure',
      'Compare Redis identity, memory pressure, eviction counters, client connections and slow-command evidence without scanning the keyspace.',
      'Redis CLI against a permitted Redis endpoint. Examples use a local endpoint on 127.0.0.1:6379; ACL permissions and managed-service command support vary.',
      'Use an existing authenticated session or approved credential mechanism. Adapt host, TLS and authentication options to your environment; do not place passwords in shared command lines. No key writes, KEYS, MONITOR or configuration changes are used.',
      [('Redis INFO command', 'https://redis.io/docs/latest/commands/info/'),
       ('Redis SLOWLOG GET', 'https://redis.io/docs/latest/commands/slowlog-get/'),
       ('Redis PING', 'https://redis.io/docs/latest/commands/ping/')], [
          ('redis-cli -h 127.0.0.1 -p 6379 PING', 'Test the selected Redis endpoint',
           'A PONG confirms the server answered this command on this connection. It does not prove application authorization, cache-hit behavior or acceptable latency under load. An authentication or ACL error is different from a connection timeout.'),
          ('redis-cli -h 127.0.0.1 -p 6379 INFO server', 'Identify the server and uptime',
           'Record version, server mode and uptime to correlate a restart with the incident. In clustered or replicated deployments, one endpoint does not represent all nodes; confirm which node the application actually uses.'),
          ('redis-cli -h 127.0.0.1 -p 6379 INFO memory', 'Inspect memory use and configured limits',
           'Compare used_memory, used_memory_rss, maxmemory and maxmemory_policy. RSS and allocator memory measure different things. A zero maxmemory value is not evidence of unlimited physical RAM; host or container limits can still apply.'),
          ('redis-cli -h 127.0.0.1 -p 6379 INFO stats', 'Compare eviction and cache counters',
           'Capture evicted_keys, keyspace_hits and keyspace_misses twice with timestamps. These are cumulative counters, so a historical nonzero value does not prove an active incident. Compare deltas and the workload mix, not only totals.'),
          ('redis-cli -h 127.0.0.1 -p 6379 INFO clients', 'Inspect connection pressure',
           'Compare connected_clients and blocked_clients with normal operation and application connection-pool settings. Blocked clients may be legitimate consumers using blocking commands; they are not automatically evidence of a hung server.'),
          ('redis-cli -h 127.0.0.1 -p 6379 SLOWLOG GET 10', 'Read a bounded slow-command sample',
           'Inspect execution time and command shape. Slowlog measures command execution rather than all client/network waiting and contains only retained entries above its configured threshold. Arguments can expose data, so redact them before sharing.')],
      ('Cache misses rise during a memory-pressure incident',
       'An application reports more backend reads and slower responses while Redis remains reachable.',
       [(0, 'Confirm the application endpoint answers; availability alone does not establish useful cache performance.'),
        (2, 'Compare memory with maxmemory and record the configured eviction policy.'),
        (3, 'Collect two counter samples. In this example evicted_keys and keyspace_misses both increase during the incident.'),
        (5, 'Check retained slow commands as a separate signal; their absence does not rule out network or client delays.')],
       'Illustrative findings: PONG succeeds; used_memory is near maxmemory; evicted_keys rises between samples; the workload has increasing misses.',
       'The samples support active eviction under memory pressure. They do not establish whether sizing, TTL choices or workload growth caused it, and cache misses can have other explanations.',
       'After the owner applies an approved sizing or retention adjustment, compare the same counter deltas under similar load. Confirm application hit behavior, latency and host memory headroom.',
       'Provide the node identity, memory policy, timestamped counter deltas and redacted slow-command shapes to the cache/application owner. Avoid dumping keys or values.'))

guide('PostgreSQL session and blocking investigation', 'PostgreSQL', 'Infrastructure',
      'Inspect database identity, connection counts, wait events, blocking relationships and long transactions using bounded SQL queries.',
      'PostgreSQL 14–18 with a connected SQL client. Broader session visibility may require pg_read_all_stats or an approved monitoring role.',
      'Connect to the intended database using your normal secure client. Run these SELECT statements in autocommit for fresh samples. Query text and session metadata can expose application data; no sessions are cancelled or terminated.',
      [('PostgreSQL activity statistics', 'https://www.postgresql.org/docs/current/monitoring-stats.html'),
       ('PostgreSQL system information functions', 'https://www.postgresql.org/docs/current/functions-info.html')], [
          ('SELECT current_database(), current_user, inet_server_addr(), inet_server_port();', 'Confirm database and server identity',
           'Match database, user and endpoint with the incident. A local Unix-domain socket can return a null network address. A connection proxy or service alias can route to different servers, so record the identity before comparing sessions.'),
          ('SELECT datname, state, count(*) FROM pg_stat_activity GROUP BY datname, state ORDER BY count(*) DESC;', 'Summarize connections by state',
           'Compare active, idle and idle-in-transaction counts with the normal connection pool. An idle session is not necessarily a leak. Visibility depends on privileges, and this snapshot does not reveal historical peaks by itself.'),
          ("SELECT pid, usename, state, wait_event_type, wait_event, now()-query_start AS query_age FROM pg_stat_activity WHERE state <> 'idle' AND pid <> pg_backend_pid() ORDER BY query_start LIMIT 20;", 'Inspect a bounded set of active waits',
           'Use wait_event_type and wait_event to separate lock waiting from other waits. Query age includes time waiting and does not prove CPU use. The monitoring query excludes its own backend but may still include unrelated long-running maintenance.'),
          ('SELECT pid AS waiting_pid, pg_blocking_pids(pid) AS blocking_pids FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid)) > 0 LIMIT 20;', 'Identify current blocking relationships',
           'Record waiting and blocking process IDs while the issue is occurring. Relationships can change between samples. A blocker may itself be waiting on another transaction, so trace the chain with the database owner instead of terminating the first PID found.'),
          ("SELECT pid, usename, state, now()-xact_start AS transaction_age FROM pg_stat_activity WHERE xact_start IS NOT NULL AND pid <> pg_backend_pid() ORDER BY xact_start LIMIT 20;", 'Find long-lived transactions',
           'Compare transaction age and state with the incident. An idle-in-transaction session can retain locks or delay cleanup, but age alone does not establish impact. Associate it with application ownership before any corrective action.'),
          ('SELECT datname, numbackends, deadlocks, stats_reset FROM pg_stat_database WHERE datname = current_database();', 'Inspect database counters with their reset time',
           'Read deadlocks as a cumulative counter since stats_reset, not a live count of blocked queries. A blocking wait is not automatically a deadlock. Compare timed samples and database logs when establishing whether new deadlocks occurred.')],
      ('Requests stall behind an idle transaction',
       'Application updates hang while the database is reachable and most connections appear idle.',
       [(0, 'Confirm the affected database and endpoint before interpreting process IDs.'),
        (2, 'Identify sessions reporting a lock wait during the user-visible stall.'),
        (3, 'Map each waiter to its blocker. In this fictional example several sessions point to one PID.'),
        (4, 'Inspect transaction age and state for that PID. The example blocker is idle in transaction from an application session.')],
       'Illustrative findings: several active requests wait on Lock; their blocking PID is the same; that backend is idle in transaction with an older xact_start.',
       'The blocking relationship supports a transaction-lifecycle problem. Being idle alone is not the cause; the open transaction and its retained locks matter. Review the application path that failed to finish the transaction.',
       'After the owner completes or rolls back the transaction through the approved process, repeat the blocking query and a normal application request. Confirm the waits clear and the pattern does not immediately recur.',
       'Provide the database, waiting/blocking PIDs, transaction age and incident times to the DBA and application owner. Share SQL text only through an approved private channel.'))

guide('MySQL connection and InnoDB lock investigation', 'MySQL', 'Infrastructure',
      'Inspect MySQL identity, connection saturation, running sessions, active InnoDB transactions and lock dependencies.',
      'MySQL 8.0/8.4 SQL client. Performance Schema access and PROCESS visibility depend on the monitoring account privileges.',
      'Use an existing secure connection to the affected instance. These statements inspect metadata without killing connections or changing global settings. Queries and process metadata may contain sensitive information.',
      [('MySQL SHOW PROCESSLIST', 'https://dev.mysql.com/doc/refman/8.4/en/show-processlist.html'),
       ('MySQL data_lock_waits table', 'https://dev.mysql.com/doc/refman/8.4/en/performance-schema-data-lock-waits-table.html'),
       ('MySQL INNODB_TRX table', 'https://dev.mysql.com/doc/refman/8.4/en/information-schema-innodb-trx-table.html')], [
          ('SELECT VERSION(), @@hostname, @@port, DATABASE(), CURRENT_USER();', 'Identify server and authenticated account',
           'Compare version, server host, port and current database with the incident environment. CURRENT_USER identifies the privilege account used by MySQL, which can differ from the client-supplied login identity. A null database can simply mean none was selected.'),
          ("SHOW GLOBAL STATUS WHERE Variable_name IN ('Threads_connected','Threads_running','Max_used_connections','Aborted_connects');", 'Inspect connection and activity counters',
           'Compare current connections and running threads with a healthy baseline. Max_used_connections is a recorded peak; Aborted_connects is cumulative. Neither value alone proves the current application is hitting its connection limit.'),
          ("SHOW GLOBAL VARIABLES LIKE 'max_connections';", 'Read the configured connection ceiling',
           'Compare the ceiling with current connections and application pool sizes across all instances. A higher ceiling is not a free performance improvement; additional sessions consume resources and can increase contention.'),
          ('SHOW FULL PROCESSLIST;', 'Inspect visible sessions and their state',
           'Look for long-running commands, waits and repeated application users. FULL includes complete statement text, so avoid sharing raw results. Without the relevant privileges you may see only your own sessions; a short list does not prove the server is quiet.'),
          ('SELECT trx_id, trx_state, trx_started, trx_mysql_thread_id FROM information_schema.innodb_trx ORDER BY trx_started LIMIT 20;', 'Inspect older InnoDB transactions',
           'Compare transaction start time and state with the incident. trx_mysql_thread_id links to the connection identity shown in processlist. An old transaction is a lead, not proof that it blocks other transactions; check the wait relationships next.'),
          ('SELECT REQUESTING_ENGINE_TRANSACTION_ID, BLOCKING_ENGINE_TRANSACTION_ID FROM performance_schema.data_lock_waits LIMIT 20;', 'Inspect current data-lock dependencies',
           'Map requesting and blocking transaction IDs to INNODB_TRX while the wait exists. This is a changing snapshot, not a history of all lock incidents, and metadata-lock waits need a different view. Multiple blockers can exist for a request.')],
      ('An update queue grows behind one transaction',
       'Application updates slow down while read requests continue and the connection count is below its ceiling.',
       [(1, 'Record current connection/activity values before attributing the incident to connection exhaustion.'),
        (3, 'Inspect session states and correlate long waits with the affected application user.'),
        (4, 'Record transaction IDs and their connection IDs for older open transactions.'),
        (5, 'Map current lock dependencies. In this example several requesting transaction IDs point to one blocker.')],
       'Illustrative findings: connections are below max_connections; several InnoDB requests wait behind one older transaction; the application pool retains its connection.',
       'The wait graph supports lock contention rather than connection saturation. Determine why the blocking transaction remains open before recommending a session termination or a timeout change.',
       'After the owner resolves the transaction through the approved process, repeat the lock and process views. Verify a representative update completes and that application latency returns to baseline.',
       'Provide server identity, transaction/connection IDs, wait samples and start times to the DBA/application owner. Redact literal SQL values and avoid sending full processlist output publicly.'))

guide('NGINX reverse proxy upstream investigation', 'NGINX', 'Networking',
      'Connect configuration tests, service logs, listener state and direct upstream requests during a reverse-proxy outage.',
      'NGINX on a systemd-based Linux host; log paths, executable paths and service names vary by installation.',
      'Use authorized read access and replace the log paths, app.example.com and 127.0.0.1:8080 with your configured values. nginx -t validates and opens referenced files; it does not reload running workers.',
      [('NGINX command-line parameters', 'https://nginx.org/en/docs/switches.html'),
       ('NGINX logging documentation', 'https://docs.nginx.com/nginx/admin-guide/monitoring/logging/'),
       ('NGINX proxy module', 'https://nginx.org/en/docs/http/ngx_http_proxy_module.html')], [
          ('nginx -t', 'Test the selected configuration files',
           'Read the tested configuration path and any filename/line error. File permissions can make the test fail under a different account from the service. A successful test does not show that the running workers have loaded the same on-disk configuration.'),
          ('systemctl status nginx.service --no-pager --full', 'Check the proxy service state',
           'Record active state, PID and recent events. A running service may still return upstream errors or serve an older configuration. Compare the incident time with restarts and deployment history rather than restarting solely to change the status.'),
          ('journalctl -u nginx.service --since "30 minutes ago" -n 100 --no-pager', 'Inspect recent service-level events',
           'Look for startup, reload and service errors around the incident. Application request details may be written to separate files or another logging destination, so an empty journal excerpt does not rule out proxy errors.'),
          ('tail -n 100 /var/log/nginx/error.log', 'Read a bounded proxy error sample',
           'Correlate the request time and upstream address with the incident. Connection refused, timeout and certificate verification errors describe different failure paths. Use the configured destination if errors go to stderr, syslog or another file.'),
          ('ss -ltnp', 'Compare proxy and upstream TCP listeners',
           'Check the expected proxy port and local upstream port, if the upstream is on this host. A missing local listener supports a service or binding issue. For a remote upstream, a local socket listing cannot establish whether it is listening remotely.'),
          ('curl --silent --show-error --output /dev/null --write-out "%{http_code}\\n" --connect-timeout 5 --max-time 15 -H "Host: app.example.com" http://127.0.0.1:8080/health', 'Test the configured local upstream directly',
           'Use the intended protocol, path and host header; do not substitute HTTP for an HTTPS upstream. This bypasses the proxy and therefore cannot validate the external TLS listener, proxy routing or authentication behavior.')],
      ('The public site returns 502 after an application restart',
       'NGINX remains active but requests return Bad Gateway after the backend deployment.',
       [(0, 'Check that the on-disk configuration can be parsed; distinguish this from whether it is loaded.'),
        (3, 'Read the exact upstream error. The example reports connection refused at 127.0.0.1:8080.'),
        (4, 'Compare local listeners. No process is listening on the configured upstream port in this scenario.'),
        (5, 'Test the same upstream endpoint directly. It also refuses the connection, independently of public DNS and client TLS.')],
       'Illustrative findings: nginx configuration test succeeds; workers remain active; error log reports upstream connection refused; TCP 8080 has no listener.',
       'The evidence points to the backend listener or its configured address. Changing proxy timeouts will not create the missing listener. Confirm whether deployment changed the backend port or stopped the service.',
       'After the application owner restores the intended listener or the proxy owner approves the corrected upstream, verify direct health response and a normal request through the public hostname. Compare fresh error-log entries.',
       'Provide the upstream address, request time, log error and listener result to the backend/proxy owners. Include only the relevant configuration excerpt, with credentials removed.'))

guide('Windows time synchronization investigation', 'Windows', 'IT fundamentals',
      'Inspect time source, synchronization status, peer configuration and measured offset before forcing a clock change.',
      'Windows 10/11 or Windows Server with Windows Time service. Domain hierarchy and virtualization can influence time sources.',
      'Use the affected machine and replace dc01.corp.example with an approved reference. Some queries need elevation; stripchart sends bounded probes. This workflow does not resync, reconfigure or set the clock.',
      [('Microsoft Windows Time tools and settings', 'https://learn.microsoft.com/en-us/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings')], [
          ('Get-Service W32Time', 'Check Windows Time service status',
           'Record the service state on the affected host. A running service is not proof of synchronization, and a stopped service can reflect policy or trigger behavior. Correlate the state with configured time policy before proposing a restart.'),
          ('w32tm /query /source', 'Read the currently reported time source',
           'Compare the source with the intended domain hierarchy or approved external reference. A local clock source may explain lack of external discipline, but its meaning depends on the host role, virtualization platform and intended design.'),
          ('w32tm /query /status /verbose', 'Inspect synchronization state and last success',
           'Record last successful sync, stratum, source and any error fields. An old success time can indicate ongoing failure despite the service running. Interpret timestamps in their displayed timezone and compare with the reported incident window.'),
          ('w32tm /query /configuration', 'Inspect effective time configuration and origin',
           'Review Type, NtpServer and settings attributed to policy versus local configuration. Domain members commonly follow domain hierarchy; manually setting public peers on every member can conflict with that design. Inspect first without changing settings.'),
          ('w32tm /query /peers', 'Inspect configured peer state',
           'Compare peer addresses, mode, state and reachability context with the expected design. Peer presence does not prove recent successful synchronization. A domain-selected source and a manually configured peer list need not be identical.'),
          ('w32tm /stripchart /computer:dc01.corp.example /samples:5 /dataonly', 'Sample offset against an approved reference',
           'Compare several offsets rather than a single measurement. Stripchart probes use their own client behavior, so successful samples do not prove that Windows Time synchronization traffic or policy is functioning. A timeout can reflect filtering or reference availability.')],
      ('Authentication errors coincide with clock drift',
       'One domain workstation reports authentication failures and its clock differs noticeably from nearby systems.',
       [(0, 'Record Windows Time service status instead of immediately restarting it.'),
        (1, 'Compare the reported source with the expected domain hierarchy.'),
        (2, 'Capture the last successful synchronization and error fields.'),
        (5, 'Measure offset against the approved reference. The example shows a persistent difference across all five samples.')],
       'Illustrative findings: W32Time runs; the last successful sync is old; repeated offset measurements show a consistent several-minute difference.',
       'Clock drift is supported, but the samples alone do not establish its root cause or prove every authentication failure is time-related. Investigate source selection, policy, network reachability and virtualization time integration.',
       'After the owner restores the approved time path, confirm a recent successful sync and repeat offset samples. Retest the affected authentication flow and compare timestamps across the relevant logs.',
       'Provide host role, source, policy origin, last sync and offset samples to the domain/platform owner. Coordinate any significant clock adjustment with application owners.'))

guide('Windows SMB share access investigation', 'Windows', 'Infrastructure',
      'Separate TCP reachability, client SMB connections, share permissions, filesystem ACLs and server-side sessions.',
      'Windows SMB client and Windows file server with PowerShell SmbShare. Commands are explicitly split between client and server contexts.',
      'Replace fs01.corp.example, Projects and D:\\Shares\\Projects. Run network/client checks on the affected client and share/ACL/session checks on the actual server with authorized read privileges.',
      [('Microsoft SMB Share module', 'https://learn.microsoft.com/en-us/powershell/module/smbshare/'),
       ('Microsoft Get-SmbConnection', 'https://learn.microsoft.com/en-us/powershell/module/smbshare/get-smbconnection'),
       ('Microsoft Get-Acl', 'https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/get-acl')], [
          ('Test-NetConnection fs01.corp.example -Port 445', 'Client: test the SMB TCP endpoint',
           'Check TcpTestSucceeded and the selected source address from the affected client. TCP success does not establish SMB authentication or file permissions. Name resolution failure, TCP refusal and TCP timeout require different follow-up checks.'),
          ('Get-SmbConnection | Select-Object ServerName,ShareName,UserName,Dialect', 'Client: inspect existing SMB connection identity',
           'Compare server, share and user with the identity expected for the failing operation. Existing connections are context-dependent; run in the relevant user session. An empty list can mean no active SMB connection, not proof that the share is unavailable.'),
          ('Get-SmbShare -Name Projects | Select-Object Name,Path,Description', 'Server: identify the share and backing path',
           'Run on the file server and verify the actual filesystem path. A DFS namespace or alias can lead to a different server than expected, so confirm the serving host before interpreting the share. Do not create a replacement share to make the lookup succeed.'),
          ('Get-SmbShareAccess -Name Projects', 'Server: inspect share-level permissions',
           'Compare allow and deny entries with the affected account group membership. Share permissions are only one layer: filesystem ACLs, deny entries and the actual authenticated token also affect the result. Broad share access does not establish write access to files.'),
          ("Get-Acl -LiteralPath 'D:\\Shares\\Projects' | Format-List Owner,AccessToString", 'Server: inspect the backing directory ACL',
           'Compare inherited and explicit entries on the actual failing path, not only the share root. This is an ACL listing rather than an effective-access calculation; nested group membership, deny entries and child permissions need separate evaluation.'),
          ('Get-SmbSession | Select-Object ClientComputerName,ClientUserName,NumOpens', 'Server: inspect current client sessions',
           'Match the affected client and user at the incident time. A session can exist while a particular file operation is denied. Missing sessions can reflect a failure before session establishment, idle disconnects or a different serving node.')],
      ('A user can browse a share but cannot save files',
       'One user opens the Projects share but receives Access Denied when saving a document.',
       [(1, 'Verify which user identity the client SMB connection actually uses.'),
        (2, 'Confirm the serving host and the filesystem path behind Projects.'),
        (3, 'Inspect the share permissions. The fictional example grants the relevant group Change access.'),
        (4, 'Inspect the actual failing directory. In this example its filesystem ACL grants that user group only read access.')],
       'Illustrative findings: SMB connects as the intended user; share permissions allow changes; the target directory filesystem ACL allows read access only.',
       'The filesystem permission layer is a supported blocker in this example. Do not replace it with broad Full Control; determine the intended business access and evaluate the complete effective token and ACL.',
       'After the access owner approves a scoped permission correction, have the affected user create, edit and delete an approved test file in that directory. Recheck access without changing unrelated shares.',
       'Provide client user context, serving node, exact directory and relevant ACL entries to the file-service/access owner. Avoid sharing file contents or full user inventories.'))

guide('Windows Group Policy application investigation', 'Active Directory', 'Identity & Microsoft 365',
      'Compare endpoint policy results, processing events, domain GPO inventory, OU inheritance and configured settings.',
      'Domain-joined Windows endpoints plus a management host with RSAT GroupPolicy. User and computer policy processing are separate scopes.',
      'Run gpresult and event-log checks on the affected endpoint; run domain GPO commands from an authorized RSAT session. Replace Workstation Baseline and the OU distinguished name. No gpupdate or policy changes are performed.',
      [('Microsoft gpresult command', 'https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/gpresult'),
       ('Microsoft GroupPolicy module', 'https://learn.microsoft.com/en-us/powershell/module/grouppolicy/'),
       ('Microsoft Get-GPInheritance', 'https://learn.microsoft.com/en-us/powershell/module/grouppolicy/get-gpinheritance')], [
          ('gpresult /r /scope user', 'Endpoint: inspect the current user policy result',
           'Run in the affected user context and record applied and denied GPOs where shown. This reports the recorded processing result, not a live prediction after an administrator edits a link. A different logged-on account can produce a different result.'),
          ('gpresult /r /scope computer', 'Endpoint: inspect computer policy separately',
           'Use an elevated authorized session where needed and compare the machine result with the user result. A user setting cannot be diagnosed solely from computer scope. Missing RSoP data may mean processing or visibility problems rather than no applicable GPOs.'),
          ("Get-WinEvent -LogName 'Microsoft-Windows-GroupPolicy/Operational' -MaxEvents 50", 'Endpoint: read recent policy-processing events',
           'Correlate processing times, activity IDs and extension errors with the relevant sign-in or refresh. The latest 50 events may not include the incident, so use a bounded time filter when needed. Read event details rather than interpreting event numbers alone.'),
          ('Get-GPO -All | Select-Object DisplayName,Id,GpoStatus,ModificationTime', 'RSAT: inspect the domain GPO inventory',
           'Confirm the intended policy exists and inspect whether its user or computer settings are disabled. Inventory presence does not prove a policy is linked, readable, in scope or successfully processed on the endpoint.'),
          ("Get-GPInheritance -Target 'OU=Workstations,DC=corp,DC=example'", 'RSAT: inspect OU links and inherited policies',
           'Replace the target with the computer or user actual OU and examine direct and inherited links, enforcement and inheritance behavior. This does not fully evaluate security filtering, WMI filtering or loopback processing for an individual endpoint.'),
          ("Get-GPOReport -Name 'Workstation Baseline' -ReportType Xml", 'RSAT: inspect the configured policy report',
           'Read the relevant setting and configured filters in the XML returned to the console. This is configuration evidence, not endpoint resultant policy. Reports can contain internal paths and security details; share only the necessary excerpt.')],
      ('A workstation never receives its new baseline',
       'A new workstation lacks the expected computer policy settings even though the baseline GPO exists in the domain.',
       [(1, 'Capture the computer policy result from the affected endpoint, with the correct privileges.'),
        (2, 'Check the corresponding processing window for errors before assuming filtering or linking is the cause.'),
        (3, 'Confirm the baseline GPO exists and its computer settings are enabled.'),
        (4, 'Inspect the workstation actual OU. In the fictional example it is in a staging OU where the baseline is not linked or inherited.')],
       'Illustrative findings: the baseline is absent from applied computer GPOs; the domain GPO is enabled; the workstation is in a staging OU without its link.',
       'The OU/link mismatch supports a scope problem. GPO existence alone does not make it applicable. Verify the intended placement and check filtering, replication and loopback if the link evidence does not explain the result.',
       'After the directory owner corrects placement or linking through the approved process, allow normal policy processing or an approved refresh. Repeat computer gpresult and verify the specific intended setting on the endpoint.',
       'Provide endpoint identity, actual OU, GPO GUID, scope, processing time and the relevant event details to the directory owner. Avoid moving accounts or changing links merely to test a hypothesis.'))

# VMware Cloud Foundation 9 references; platform-specific recovery and licensing workflows.
guide('VCF 9 ESXi host root password recovery', 'VMware VCF', 'Infrastructure',
 'Recover a managed ESXi host root account through vCenter and PowerCLI, and reconcile VCF credential management.',
 'VCF 9 with ESXi 9 managed by a connected vCenter; this procedure changes the selected host root password.',
 'Use an authorized vCenter administrative account and approved maintenance process. Confirm the exact host, VCF password-management policy and recovery access. The host must be connected and responding; vpxuser shell access must not be disabled. Do not record passwords in tickets or transcripts.',
 [('Broadcom ESXi root recovery using PowerCLI','https://knowledge.broadcom.com/external/article/376979/reset-password-for-root-account-of-esxi.html'),('Broadcom configuration profile password drift','https://knowledge.broadcom.com/external/article/404104/reset-root-password-using-vsphere-config.html'),('Broadcom ESXi recovery with another local administrator','https://knowledge.broadcom.com/external/article/409618')], [
 ('Connect-VIServer -Server vcsa.example.com', 'Connect to the correct vCenter', 'Authenticate interactively with an authorized administrative account and verify the vCenter identity. The target host must be managed by this vCenter and connected; do not use this method for a disconnected standalone host.'),
 ('$hostObject = Get-VMHost -Name esx01.example.com', 'Select and verify the target host', 'Replace the example with the exact inventory name. Check the returned host and connection state before proceeding. If multiple vCenter connections exist, scope the command to the intended server to avoid selecting a different host.'),
 ('$credential = Get-Credential -UserName root -Message "Enter the new ESXi root password"', 'Collect the new password interactively', 'Enter the new root password in the secure credential prompt, following host password policy. Avoid embedding it in scripts, shell history, command lines or support tickets. The host validates its password requirements.'),
 ('$esxcli = Get-EsxCli -VMHost $hostObject -V2', 'Obtain the host ESXCLI interface', 'This obtains the versioned interface for the selected host. Confirm the target again; the next commands prepare and execute a real password change on that host.'),
 ('$args = $esxcli.system.account.set.CreateArgs(); $args.id = $credential.UserName; $args.password = $credential.GetNetworkCredential().Password; $args.passwordconfirmation = $credential.GetNetworkCredential().Password', 'Prepare the account change arguments', 'This holds the password in the current PowerShell process memory. Do not print or export the argument object. Use a private session and clear credential variables after the approved operation.'),
 ('$esxcli.system.account.set.Invoke($args)', 'Apply the approved root password change', 'This changes the root password on the selected ESXi host. Broadcom documents a true result on success. Verify access through an approved path and reconcile SDDC Manager and configuration-profile credentials using the supported workflow.')],
 ('A managed host root password no longer works','A connected VCF-managed ESXi host rejects the recorded root password, while vCenter administrative access remains available.',[(0,'Confirm the vCenter endpoint and sign in with an authorized administrator.'),(1,'Check the inventory name and ensure that the host is connected and responding.'),(2,'Collect the replacement password in a secure prompt without saving it in a script.'),(3,'Create the ESXCLI interface for the verified host; prepare and invoke the account change only after authorization.')],
 'Example: vCenter is reachable and the target host is connected, so the documented PowerCLI recovery path is available.', 'A connected management path makes the documented host account update possible; it does not reset vCenter appliance root or automatically reconcile all VCF credential records.', 'Confirm the operation returns true, test access through the approved administrative path, and use VCF credential-management remediation and configuration-profile compliance checks as applicable.', 'Escalate disconnected hosts, failed privileges or profile drift to the VCF administrator and Broadcom support. Do not repeatedly try passwords or reinstall a host as a first step.'))
NEW_GUIDES[-1]['updated']='2026-11-03'

guide('VCF 9 license server deployment and registration', 'VMware VCF', 'Infrastructure',
 'Plan and verify the dedicated VCF License Server deployment and registration for VCF 9.1.',
 'VCF 9.1 and VCF Operations 9.1. Licensing architecture differs in 9.0; verify the exact release and upgrade path before deployment.',
 'Use the release-specific Broadcom deployment guide, supported OVA and an authorized VCF administrator. Prepare the required DNS, network, certificates and capacity per the official version-specific checklist. UI labels and workflows vary by release.',
 [('Broadcom missing License Server recovery','https://knowledge.broadcom.com/external/article/453149/unable-to-update-license-keys-in-vcf-ope.html'),('Broadcom VCF 9.1 licensing overview','https://knowledge.broadcom.com/external/article/440471'),('Broadcom 9.0 and 9.1 deployment distinction','https://knowledge.broadcom.com/external/article/423051/manual-deployment-of-vcf-operations-in-a.html')], [
 ('Verify product version and entitlement', 'Identify the correct licensing architecture', 'Record the installed VCF and Operations releases and confirm entitlement in the Business Services Console. The dedicated License Server is a VCF 9.1 component; do not assume the same deployment workflow applies to every 9.0 environment.'),
 ('VCF Operations → Licenses & Registration → Manage → License Servers', 'Inspect existing License Server registration', 'Check whether a server is already listed, its state and the existing licensing environment. Record the current registration before creating a duplicate appliance or replacing an existing server.'),
 ('Prepare the approved VCF 9.1 deployment inputs', 'Validate deployment prerequisites', 'Use the exact Broadcom guide for the deployment or upgrade path. Confirm supported OVA, management network, DNS records, addresses, time synchronization, certificates and required connectivity using its release-specific requirements.'),
 ('Deploy VCF Management Services and License Server', 'Deploy the supported appliance', 'Follow the version-specific VCF deployment or upgrade workflow referenced by Broadcom. Supply the approved infrastructure and networking values, then wait for the workflow and appliance initialization to complete. Do not substitute VVF-only manual deployment instructions for VCF.'),
 ('Register VCF Operations and License Server with Business Services Console', 'Establish the licensing registration', 'Complete the registration procedure for both components using the appropriate connected or disconnected workflow. Confirm the appliance appears in License Servers and check registration and usage reporting status.'),
 ('VCF Operations → Licenses & Registration → Version 9+', 'Review and assign active entitlements', 'Use the approved active primary entitlements for the applicable vCenter and ESXi hosts. Verify allocation, usage reporting and licensing state after synchronization; keep license keys and account details out of shared incident notes.')],
 ('License allocation fails after a 9.1 upgrade','VCF Operations reports a usage deadline and its License Servers view has no deployed appliance.',[(0,'Confirm that this environment is actually VCF 9.1 and record its entitlement status.'),(1,'Inspect the License Servers view and determine whether an appliance is missing or merely disconnected.'),(2,'Complete the exact release-specific deployment prerequisites with the infrastructure owner.'),(3,'Deploy the required components through the documented VCF upgrade workflow, then register both components.')],
 'Example: VCF Operations 9.1 shows no License Server and warns that a usage report is overdue.', 'A missing appliance is a documented cause of licensing failure in VCF 9.1. Verify connectivity and registration separately when a License Server already exists.', 'Confirm the server appears as registered, report usage using the approved method, and verify active allocations and host licensing state.', 'Escalate entitlement, deployment or registration errors with the VCF version, task ID and sanitized logs. For offline sites follow Broadcom disconnected licensing documentation.'))
NEW_GUIDES[-1]['kind']='Step'
